// What a response has to match to be this request's, checked with real KMS shares.
//
// `solana/test-fixtures/user-decrypt/threshold-wasm-transcript.json` is a 4-party threshold user
// decryption for a Solana user. It is regenerated by hand, not by the TKMS regen script: in kms, at
// the commit the vendored WASM is built from (src/wasm/tkms/KMS_BUILT_FROM), run
// `cargo test test_user_decryption_threshold_and_write_transcript -F wasm_tests --release` (the
// TestHost::Solana case writes `temp/test-solana-threshold-wasm-transcript.8.json`) and copy that
// file here. Its shares are real signcryptions, so each case below changes one input the client
// brings and checks which rule refuses the untouched shares.
//
// The transcript's handle is an opaque 8-byte KMS test input, not an SDK handle. So a response that
// passes every KMS client rule stops at this module's typed-answer check, which needs a 32-byte
// handle. That stop is the control: it proves the signature, link and threshold rules passed. The
// plaintext itself is pinned by one call to the WASM client directly.

import type { Address } from '@solana/kit';
import type { SolanaTransportKeyPair, SolanaUserDecryptRequestInputs } from './index.js';
import { readFileSync } from 'node:fs';
import { getAddressEncoder } from '@solana/kit';
import { beforeAll, describe, expect, it } from 'vitest';
import { initTkmsModule } from '../../core/modules/decrypt/module/init-p.js';
import { setFhevmRuntimeConfig } from '../internal/config.js';
import { getSolanaRuntime } from '../internal/runtime.js';
import { verifySolanaUserDecryptPlaintexts, verifySolanaUserDecryptResponse } from './index.js';
import { hexToBytes } from '../../core/base/bytes.js';

/* eslint-disable @typescript-eslint/naming-convention -- KMS transcript wire fields */
interface Transcript {
  fhe_parameter: string;
  client_address: string;
  server_addrs: { id: number; addr: string }[];
  request: {
    client_address: string;
    enc_key: string;
    ciphertext_handles: string[];
    eip712_verifying_contract: string;
    extra_data: string;
  };
  eip712_domain: { name: string; version: string; chain_id: number[]; verifying_contract: string };
  responses: { signature: string; payload: string; extra_data: string }[];
  enc_pk: string;
  enc_sk: string;
  expected: { fhe_type: number; plaintext_hex: string }[];
}
/* eslint-enable @typescript-eslint/naming-convention */

const transcript = JSON.parse(
  readFileSync(
    new URL('../../../../../solana/test-fixtures/user-decrypt/threshold-wasm-transcript.json', import.meta.url),
    'utf8',
  ),
) as Transcript;

const unhex = (hex: string): Uint8Array => hexToBytes(`0x${hex}`);

const request: SolanaUserDecryptRequestInputs = {
  userAddress: Uint8Array.from(getAddressEncoder().encode(transcript.client_address as Address)),
  handles: transcript.request.ciphertext_handles.map(unhex),
  transportKey: unhex(transcript.request.enc_key),
  gatewayEip712Domain: {
    name: transcript.eip712_domain.name,
    version: transcript.eip712_domain.version,
    chainId: BigInt(`0x${Buffer.from(transcript.eip712_domain.chain_id).toString('hex')}`),
    verifyingContract: transcript.eip712_domain.verifying_contract,
  },
  extraData: unhex(transcript.request.extra_data),
};

const shares = transcript.responses.map((share) => ({
  signature: share.signature,
  payload: share.payload,
  extraData: share.extra_data,
}));

const signers = transcript.server_addrs.map(({ id, addr }) => ({ partyId: id, address: addr }));

/** Passed every KMS client rule, and stopped at the typed answer on the transcript's 8-byte handle. */
const PASSED_THE_CLIENT = /the handle at position 0 is not a 32-byte handle/;
/** Every share's node signature failed, so none counts toward the threshold. */
const NODE_SIGNATURE = /Not enough correct responses/;
const LINK_MISMATCH = /not linked to the correct request/;

let keyPair: SolanaTransportKeyPair;

beforeAll(async () => {
  setFhevmRuntimeConfig({});
  const kmsLib = await initTkmsModule(getSolanaRuntime());
  const secretKey = kmsLib.u8vec_to_ml_kem_pke_sk(unhex(transcript.enc_sk));
  keyPair = { secretKey, publicKey: kmsLib.ml_kem_pke_get_pk(secretKey), publicKeyBytes: unhex(transcript.enc_pk) };
});

const verify = (overrides: {
  readonly request?: Partial<SolanaUserDecryptRequestInputs>;
  readonly shares?: typeof shares;
  readonly signers?: typeof signers;
}) =>
  verifySolanaUserDecryptResponse({
    runtime: getSolanaRuntime(),
    request: { ...request, ...overrides.request },
    shares: overrides.shares ?? shares,
    keyPair,
    signers: overrides.signers ?? signers,
    fheParameter: transcript.fhe_parameter,
  });

/** The same bytes with one flipped, at `index`. */
const flippedAt = (bytes: Uint8Array, index: number): Uint8Array =>
  bytes.map((byte, at) => (at === index ? byte ^ 0x01 : byte));

describe('the shared KMS client, on a Solana user', () => {
  it('recovers the transcript plaintext from a base58 user address', async () => {
    const kmsLib = await initTkmsModule(getSolanaRuntime());
    const client = kmsLib.new_client(
      signers.map((signer) => kmsLib.new_server_id_addr(signer.partyId, signer.address)),
      transcript.client_address,
      transcript.fhe_parameter,
    );
    try {
      const plaintexts = kmsLib.process_user_decryption_resp_from_js(
        client,
        { signature: undefined, ...transcript.request },
        { ...transcript.eip712_domain, chain_id: Uint8Array.from(transcript.eip712_domain.chain_id), salt: null },
        transcript.responses,
        keyPair.publicKey,
        keyPair.secretKey,
        undefined,
        true,
      );
      expect(
        plaintexts.map((plaintext) => ({
          fhe_type: plaintext.fhe_type,
          // Rust transcripts store little endian; the JS API returns big endian.
          plaintext_hex: Buffer.from(plaintext.bytes).reverse().toString('hex'),
        })),
      ).toEqual(transcript.expected);
    } finally {
      client.free();
    }
  });
});

describe('the response verification', () => {
  // No shares is not an empty answer: it is a response that reaches no threshold. "Nothing was
  // decrypted" has to fail, not decode.
  it('refuses a response with no shares at all', async () => {
    await expect(verify({ shares: [] })).rejects.toThrow(/no shares/);
  });

  it('passes every client rule for the transcript request', async () => {
    await expect(verify({})).rejects.toThrow(PASSED_THE_CLIENT);
  });

  // The KMS left-pads handles to 32 bytes before linking them, so the zero-padded transcript handle
  // keeps the link. Its type byte reads as ebool, while the shares decrypt to a euint8: the
  // recovered plaintext reaches the typed answer, and the typed answer refuses it.
  it('hands the recovered plaintext to the typed answer', async () => {
    const [handle] = request.handles;
    if (handle === undefined) throw new Error('the transcript has no handle');
    const padded = new Uint8Array(32);
    padded.set(handle, 32 - handle.length);
    await expect(verify({ request: { handles: [padded] } })).rejects.toThrow(
      'plaintext 0 is of FHE type 2, and the handle at that position asks for type 0',
    );
  });

  it('refuses the shares once the request names another handle', async () => {
    const [handle] = request.handles;
    if (handle === undefined) throw new Error('the transcript has no handle');
    await expect(verify({ request: { handles: [flippedAt(handle, handle.length - 1)] } })).rejects.toThrow(
      LINK_MISMATCH,
    );
  });

  // The node signs over the transport key, so another key refuses the shares by the signature rule.
  it('refuses the shares once the request carries another transport key', async () => {
    await expect(
      verify({ request: { transportKey: flippedAt(request.transportKey, request.transportKey.length - 1) } }),
    ).rejects.toThrow(NODE_SIGNATURE);
  });

  // The client derives t from the signer count, n = 3t + 1, and needs 2t + 1 authenticated shares
  // from distinct parties. The rule lives in the KMS WASM, so this boundary pair is its evidence.
  it('passes 2t + 1 shares and refuses 2t', async () => {
    const t = (signers.length - 1) / 3;
    await expect(verify({ shares: shares.slice(0, 2 * t + 1) })).rejects.toThrow(PASSED_THE_CLIENT);
    await expect(verify({ shares: shares.slice(0, 2 * t) })).rejects.toThrow(NODE_SIGNATURE);
  });

  // A share authenticates only under its party's trusted address: a signer set that gives one
  // included share's party an address that signed nothing leaves 2t, which is too few.
  it('refuses 2t + 1 shares once one of their parties has a foreign address', async () => {
    // Share order is not party order. Shares 0-2 are parties 3, 4 and 2; share 3 is party 1.
    const threeShares = shares.slice(0, 3);
    const foreign = (partyId: number) =>
      signers.map((signer) =>
        signer.partyId === partyId ? { ...signer, address: '0x1111111111111111111111111111111111111111' } : signer,
      );
    await expect(verify({ shares: threeShares })).rejects.toThrow(PASSED_THE_CLIENT);
    await expect(verify({ shares: threeShares, signers: foreign(3) })).rejects.toThrow(NODE_SIGNATURE);
    // The control: changing the address of the one party with no share here refuses nothing.
    await expect(verify({ shares: threeShares, signers: foreign(1) })).rejects.toThrow(PASSED_THE_CLIENT);
  });

  it('refuses shares whose node signatures do not verify', async () => {
    await expect(verify({ shares: shares.map((share) => ({ ...share, signature: '00'.repeat(65) })) })).rejects.toThrow(
      NODE_SIGNATURE,
    );
  });

  // The signed message does not name the recipient, so the signature rule passes; the recomputed
  // link is another user's, and the shares do not carry it.
  it('refuses the shares once the request names another recipient', async () => {
    await expect(verify({ request: { userAddress: flippedAt(request.userAddress, 0) } })).rejects.toThrow(
      LINK_MISMATCH,
    );
  });

  // The route is the client's own: the node signature covers it, so a route that is not the one
  // the shares were signed over refuses them, from either side.
  it('refuses the shares once the request carries another KMS route', async () => {
    await expect(verify({ request: { extraData: Uint8Array.of(0x01) } })).rejects.toThrow(NODE_SIGNATURE);
  });

  it('refuses shares that carry another KMS route than the request', async () => {
    await expect(verify({ shares: shares.map((share) => ({ ...share, extraData: '01' })) })).rejects.toThrow(
      NODE_SIGNATURE,
    );
  });

  // The gateway domain is the domain the nodes signed under, so a client configured with another
  // gateway's domain refuses real shares by the signature rule, which runs first.
  it('refuses the shares under a foreign gateway domain', async () => {
    const gatewayEip712Domain = { ...request.gatewayEip712Domain, chainId: request.gatewayEip712Domain.chainId + 1n };
    await expect(verify({ request: { gatewayEip712Domain } })).rejects.toThrow(NODE_SIGNATURE);
  });

  // Configuration read from on-chain bytes is naturally all-lowercase, which the client's parser
  // would refuse as a bad checksum. The boundary re-encodes the spellings that carry no checksum; a
  // mixed-case spelling claims one, and a wrong claim stays refused.
  it('reads lowercase signer and gateway addresses as the same trust anchor', async () => {
    await expect(
      verify({
        request: {
          gatewayEip712Domain: {
            ...request.gatewayEip712Domain,
            verifyingContract: request.gatewayEip712Domain.verifyingContract.toLowerCase(),
          },
        },
        signers: signers.map((signer) => ({ ...signer, address: signer.address.toLowerCase() })),
      }),
    ).rejects.toThrow(PASSED_THE_CLIENT);
  });

  it('keeps refusing a mixed-case signer address with a wrong checksum', async () => {
    const [first, ...rest] = signers;
    if (first === undefined) throw new Error('the transcript has no signers');
    const index = [...first.address].findIndex((char, at) => at >= 2 && /[a-fA-F]/.test(char));
    const char = first.address.charAt(index);
    const flipped =
      first.address.slice(0, index) +
      (char === char.toLowerCase() ? char.toUpperCase() : char.toLowerCase()) +
      first.address.slice(index + 1);
    await expect(verify({ signers: [{ ...first, address: flipped }, ...rest] })).rejects.toThrow(/checksum/i);
  });
});

////////////////////////////////////////////////////////////////////////////////
// The typed answer: plaintexts against the handles they claim to answer
////////////////////////////////////////////////////////////////////////////////

// The link binds the handles' bytes, not the payload's type field: every link rule passes when the
// KMS answers under the right link with the wrong type.
describe('the typed answer', () => {
  /** A handle of the given FHE type: the type byte at 30, version 0 at 31. */
  const handleOfType = (fheTypeId: number): Uint8Array => {
    const handle = new Uint8Array(32).fill(0xa1);
    handle[30] = fheTypeId;
    handle[31] = 0;
    return handle;
  };
  const EBOOL = 0;
  const EUINT64 = 5;
  const plaintext = (fheTypeId: number) => ({ bytes: new Uint8Array([0x01]), fheTypeId });

  it('accepts one plaintext per handle, each of the type its handle embeds', () => {
    expect(() =>
      verifySolanaUserDecryptPlaintexts(
        [plaintext(EBOOL), plaintext(EUINT64)],
        [handleOfType(EBOOL), handleOfType(EUINT64)],
      ),
    ).not.toThrow();
  });

  // The failure this rule exists for: a euint64 released as an ebool would be decoded as one bit of
  // a value that never was a boolean, and no other rule reads the type at all.
  it('refuses a plaintext whose type is not the one its handle embeds, naming the position and both types', () => {
    expect(() =>
      verifySolanaUserDecryptPlaintexts(
        [plaintext(EBOOL), plaintext(EBOOL)],
        [handleOfType(EBOOL), handleOfType(EUINT64)],
      ),
    ).toThrow('plaintext 1 is of FHE type 0, and the handle at that position asks for type 5');
  });

  it('refuses an answer of the wrong length, in either direction', () => {
    expect(() => verifySolanaUserDecryptPlaintexts([plaintext(EBOOL)], [])).toThrow(
      'carries 1 plaintext(s) for 0 requested handle(s)',
    );
    expect(() => verifySolanaUserDecryptPlaintexts([], [handleOfType(EBOOL)])).toThrow(
      'carries 0 plaintext(s) for 1 requested handle(s)',
    );
  });
});
